float Sample(float3 p)
{
    // Wind shear. The cloud leans downwind as it rises, so the shape at
    // height y is the shape at the base, shifted sideways.
    p.xz -= shear * p.y;

    // Anvil. Widening the top is the same thing as narrowing the point you
    // are asking about, so it is a warp rather than extra geometry.
    float t = SmoothStep(anvilHeight, height, p.y);
    p.xz /= 1.0 + anvilSpread / radius * t;

    // The body: a handful of spheres, smoothly welded into each other.
    float d = lobes[0].w - length(p - lobes[0].xyz);
    for (int i = 1; i < lobeCount; i++)
        d = SmoothMax(d, lobes[i].w - length(p - lobes[i].xyz), lobeBlend);

    // Flat bottom. Intersect with the half space above the base, which is
    // the razor edge a real cumulus has.
    d = SmoothMin(d, p.y, baseSoftness);

    // Erosion. Fractal noise eats into the surface, faded in above the
    // base so the flat bottom survives it.
    float fade = SmoothStep(0.0, baseFadeHeight, p.y);
    float n = Fbm(p / erosionFeatureSize, erosionOctaves, seed);
    d += n * erosionAmplitude * fade;

    return d;   // positive inside the cloud, negative outside
}

half4 RaymarchCloud(Ray ray, Volume v, Surface s)
{
    float tNear, tFar;
    if (!IntersectBox(v, ray, tNear, tFar)) return 0;

    // Step size comes from the volume's own resolution, not from how far
    // apart the box walls happen to be. The box is about 97% empty air.
    float stepSize = v.voxelSize * s.stepScale;

    // Offset each pixel's start by up to one step. Without this every pixel
    // samples at the same depths and the error lines up into visible bands.
    float t = tNear + stepSize * Dither(pixel);

    half3 scattered = 0;
    half transmittance = 1;

    for (int i = 0; i < s.steps; i++)
    {
        // Stop once the cloud has blocked essentially all the light.
        if (t >= tFar || transmittance < 0.01) break;

        float3 p = ray.origin + ray.dir * t;

        // A coarse mip reading zero proves this whole region is empty,
        // so the ray can jump rather than crawl.
        if (SampleCoarse(v, p) <= 0) { t += skipStep; continue; }

        float density = SampleDensity(v, p);

        if (density > 1e-5)
        {
            // ****  THE ONE LINE THE NETWORK REPLACES  ****
            half3 inScatter = ShadeSample(v, s, p, ray.dir, toSun);

            // How much light this step blocks.
            half stepT = exp(-density * stepSize);

            // Add what scattered toward us, dimmed by everything in front.
            scattered += transmittance * inScatter * (1 - stepT);
            transmittance *= stepT;
        }

        t += stepSize;
    }

    return half4(scattered, 1 - transmittance);
}

// Squared ReLU: x*x for positive x, zero below. One extra multiply over
// plain ReLU, and the reason for it is visual rather than mathematical.
float Act(float x)
{
    float r = max(x, 0.0);
    return r * r;
}

float3 CloudNetEvaluate(float descriptor[13])
{
    // Standardise against the mean and scale stored alongside the weights.
    float x[13];
    [unroll] for (int i = 0; i < 13; i++)
        x[i] = (descriptor[i] - _NetMean[i]) * _NetScale[i];

    float h0[16], h1[16];

    [unroll] for (int j = 0; j < 16; j++)
    {
        float sum = _NetBias0[j];
        [unroll] for (int i = 0; i < 13; i++) sum += x[i] * _NetW0[j][i];
        h0[j] = Act(sum);
    }

    [unroll] for (int j = 0; j < 16; j++)
    {
        float sum = _NetBias1[j];
        [unroll] for (int i = 0; i < 16; i++) sum += h0[i] * _NetW1[j][i];
        h1[j] = Act(sum);
    }

    // Squaring the output keeps the result non-negative by construction.
    // A clamp would not: it has zero gradient below zero, so any output that
    // wanders negative during training is dead for the rest of the run.
    float3 y;
    [unroll] for (int k = 0; k < 3; k++)
    {
        float sum = _NetBias2[k];
        [unroll] for (int i = 0; i < 16; i++) sum += h1[i] * _NetW2[k][i];
        y[k] = sum * sum;
    }

    return min(y, _NetClamp);
}
